package main

import (
	"fmt"
)

func main() {
	var str string
	fmt.Scan(&str)
	t := 0
	i := 0
	for i = 0; i < len(str); i++ {
		diff := int(str[i] - 'a')
		if diff > t {
			fmt.Println("NO")
			break
		}
		if diff == t {
			t++
		}
	}
	if i == len(str) {
		fmt.Println("YES")
	}
}

