package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	str := scanner.Text()

	t := 0
	valid := true
	for i := 0; i < len(str); i++ {
		c := int(str[i] - 'a')
		if c > t {
			valid = false
			break
		}
		if c == t {
			t++
		}
	}

	if valid {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

